import { hasRule } from "@mdit/helper";
import type { BlockRule, InlineRule, PluginWithOptions } from "@mdit/helper";
import type { StateBlock, StateInline } from "markdown-it";

import type { MarkdownItTexOptions } from "./options.js";

const BLOCK_MARKER = String.raw`\[`;
const INLINE_MARKER = String.raw`\(`;

/*
 * Count preceding backslashes from a position
 */
const countPrecedingBackslashes = (src: string, pos: number, minPos = 0): number => {
  let count = 0;
  let checkPos = pos - 1;

  while (checkPos >= minPos && src.charCodeAt(checkPos) === 92 /* \ */) {
    count++;
    checkPos--;
  }

  return count;
};

/*
 * Test if a character code is a word character or number
 * Equivalent to regex \w which matches [a-zA-Z0-9_]
 */
const isWordCharacterOrNumber = (code: number): boolean =>
  (code >= 48 && code <= 57) || // 0-9
  (code >= 65 && code <= 90) || // A-Z
  (code >= 97 && code <= 122) || // a-z
  code === 95; // _

/*
 * Test if this position is a valid opening $ delimiter
 * Checks word boundary for opening: prevChar must be whitespace,
 * start-of-line, or non-word/non-number. Prevents `a$x$b` from parsing.
 */
const isDollarOpen = (state: StateInline, pos: number, allowInlineWithSpace: boolean): boolean => {
  const prevCharCode = state.src.charCodeAt(pos - 1);
  const nextCharCode = state.src.charCodeAt(pos + 1);
  const isSpace = state.md.utils.isSpace;

  return (
    prevCharCode !== 36 /* $ */ &&
    (pos === 0 || isSpace(prevCharCode) || !isWordCharacterOrNumber(prevCharCode)) &&
    (allowInlineWithSpace || !isSpace(nextCharCode))
  );
};

/*
 * Test if this position is a valid closing $ delimiter
 * Checks word boundary for closing: nextChar must be whitespace,
 * end-of-line, or non-word/non-number. Prevents `$x$a` from parsing.
 */
const isDollarClose = (state: StateInline, pos: number, allowInlineWithSpace: boolean): boolean => {
  const prevCharCode = state.src.charCodeAt(pos - 1);
  const nextCharCode = state.src.charCodeAt(pos + 1);
  const isSpace = state.md.utils.isSpace;

  return (
    nextCharCode !== 36 /* $ */ &&
    (nextCharCode == null || isSpace(nextCharCode) || !isWordCharacterOrNumber(nextCharCode)) &&
    (allowInlineWithSpace || !isSpace(prevCharCode))
  );
};

/*
 * Parse inline math with dollar signs: $...$
 */
const createDollarInlineTexRule =
  (allowInlineWithSpace: boolean): InlineRule =>
  (state, silent) => {
    // In silent mode markdown-it is only probing for a link/image label end, so
    // matching (and consuming) the math could swallow the closing `]`.
    if (silent || state.src[state.pos] !== "$") return false;

    if (!isDollarOpen(state, state.pos, allowInlineWithSpace)) {
      state.pending += "$";

      state.pos++;

      return true;
    }

    /*
     * First check for and bypass all properly escaped delimiters
     * This loop will assume that the first leading backtick can not
     * be the first character in state.src, which is known since
     * we have found an opening delimiter already.
     */
    let match = state.pos + 1;
    let pos: number;
    const isSpace = state.md.utils.isSpace;

    while ((match = state.src.indexOf("$", match)) !== -1) {
      // The closing $ must be inside the current inline scope (posMax),
      // otherwise the scan could cross a link/image label boundary and
      // swallow the label's tail along with the following content.
      if (match >= state.posMax) {
        match = -1;
        break;
      }

      /*
       * Found potential $, look for escapes, pos will point to
       * first non escape when complete
       */
      pos = match - 1;
      while (state.src.charCodeAt(pos) === 92 /* \ */) pos--;

      // Even number of escapes means the $ is escaped, skip it
      if ((match - pos) % 2 === 0) {
        match++;
        continue;
      }

      // Valid closing delimiter found
      if (isDollarClose(state, match, allowInlineWithSpace)) break;

      // A $ surrounded by whitespace is not a closing delimiter (unless
      // allowInlineWithSpace); it's likely a literal $ inside the content,
      // e.g. \text{a $ b}. Keep scanning for the real closing delimiter.
      // Only treat it as a literal $ when BOTH sides are whitespace, otherwise
      // it may be the opening $ of a separate inline expression (e.g. `$1 $c$`).
      const prevCharCode = state.src.charCodeAt(match - 1);
      const nextCharCode = state.src.charCodeAt(match + 1);

      if (
        !allowInlineWithSpace &&
        isSpace(prevCharCode) &&
        (match + 1 >= state.posMax || isSpace(nextCharCode))
      ) {
        match++;
        continue;
      }

      // Invalid closing delimiter, treat as no closing delimiter
      match = -1;
      break;
    }

    // No closing delimiter found.  Consume $ and continue.
    if (match === -1) {
      state.pending += "$";

      state.pos += 1;

      return true;
    }

    // Check if we have empty content, ie: $$.  Do not parse.
    if (match - (state.pos + 1) === 0) {
      state.pending += "$$";

      state.pos += 2;

      return true;
    }

    const token = state.push("math_inline", "math", 0);

    token.markup = "$";
    token.content = state.src.slice(state.pos + 1, match);

    state.pos = match + 1;

    return true;
  };

/*
 * Parse inline math with bracket syntax: \(...\)
 */
const createBracketInlineTexRule = (): InlineRule => (state, silent) => {
  const start = state.pos;
  const max = state.posMax;

  // In silent mode markdown-it is only probing for a link/image label end, so
  // matching (and consuming) the math could swallow the closing `]`.
  // Check for opening \(
  if (
    silent ||
    start + 1 >= max ||
    state.src.charCodeAt(start) !== 92 /* \ */ ||
    state.src.charCodeAt(start + 1) !== 40 /* ( */
  )
    return false;

  // Look for closing \) within the current inline scope (posMax)
  let pos = start + 2;
  let found = false;

  while (pos + 1 < max) {
    if (state.src.charCodeAt(pos) === 92 /* \ */ && state.src.charCodeAt(pos + 1) === 41 /* ) */) {
      // Check if the opening \( was escaped
      const openingBackslashes = countPrecedingBackslashes(state.src, start);

      // If opening \( is escaped (odd number of preceding backslashes), don't parse
      if (openingBackslashes % 2 === 1) return false;

      // Check if the closing \) is escaped
      const closingBackslashes = countPrecedingBackslashes(state.src, pos, start + 2);

      // If closing \) is not escaped (even number of preceding backslashes), we found it
      if (closingBackslashes % 2 === 0) {
        found = true;
        break;
      }
    }
    pos++;
  }

  if (!found) return false;

  const token = state.push("math_inline", "math", 0);

  token.markup = INLINE_MARKER;
  token.content = state.src.slice(start + 2, pos);

  state.pos = pos + 2;

  return true;
};

// Like state.skipSpacesBack, but skips markdown-it's Unicode whitespace set (e.g. NBSP)
const skipWhitespaceBack = (state: StateBlock, max: number, min: number): number => {
  const isWhiteSpace = state.md.utils.isWhiteSpace;
  let pos = max;

  while (pos > min && isWhiteSpace(state.src.charCodeAt(pos - 1))) pos--;

  return pos;
};

/*
 * Cached result of an unsuccessful closing-marker look-ahead
 *
 * The paragraph terminator probes a block rule once per line with `silent` set, so a rule that scans
 * the body for its closing marker repeats the same look-ahead for every line of a paragraph made of
 * fence lines, which is quadratic. A scan started from a later line only revisits a suffix of the
 * previous one, so the line that stopped the last unsuccessful scan answers every probe starting
 * before it without scanning again.
 *
 * Only unsuccessful scans are cached: a closing marker ends the parsing of the scanned lines, so a
 * successful scan is never asked again.
 */
interface BlockScanMiss {
  /** End of the tokenize range the scan was performed in */
  endLine: number;
  /** Block indent the scan was performed with */
  blkIndent: number;
  /** Character codes of the closing marker */
  close1: number;
  close2: number;
  /** Line the scan started from */
  from: number;
  /** Line that stopped the scan: the end of the range or a line indented below `blkIndent` */
  stop: number;
}

/*
 * Test if a line whose content starts at `pos` ends with the closing marker
 *
 * `contentEnd` is the position after the last non-whitespace character of the line, so trailing
 * whitespace is ignored and the marker must be fully inside the line.
 */
const endsWithMarker = (
  src: string,
  pos: number,
  contentEnd: number,
  close1: number,
  close2: number,
): boolean =>
  contentEnd - pos >= 2 &&
  src.charCodeAt(contentEnd - 1) === close2 &&
  src.charCodeAt(contentEnd - 2) === close1;

const blockScanMisses = new WeakMap<StateBlock, BlockScanMiss>();

/*
 * Find the line that closes a block starting at `startLine`, or -1 when there is none.
 *
 * markdown-it only mutates the leading part of a line (list markers and blockquote markers are
 * stripped) and its indent while tokenizing nested content, so whether a line *ends* with a closing
 * marker never changes: a cached miss stays valid for the same range, block indent and marker.
 */
const findBlockClose = (
  state: StateBlock,
  startLine: number,
  endLine: number,
  close1: number,
  close2: number,
): number => {
  const miss = blockScanMisses.get(state);

  if (
    miss &&
    miss.endLine === endLine &&
    miss.blkIndent === state.blkIndent &&
    miss.close1 === close1 &&
    miss.close2 === close2 &&
    startLine >= miss.from &&
    startLine < miss.stop
  )
    return -1;

  const { src } = state;
  let stop = endLine;

  for (let current = startLine + 1; current < endLine; current++) {
    const pos = state.bMarks[current] + state.tShift[current];
    const end = state.eMarks[current];

    // non-empty line with negative indent should stop the list:
    if (pos < end && state.sCount[current] < state.blkIndent) {
      stop = current;
      break;
    }

    const contentEnd = skipWhitespaceBack(state, end, pos);

    if (endsWithMarker(src, pos, contentEnd, close1, close2)) return current;
  }

  blockScanMisses.set(state, {
    blkIndent: state.blkIndent,
    close1,
    close2,
    endLine,
    from: startLine,
    stop,
  });

  return -1;
};

/*
 * Test if the rest of the line contains a single-line $$...$$ pair followed by
 * non-whitespace content, e.g. `$$a=1$$ and $b=2$`.
 *
 * In that case the line must not be treated as a block (fall back to paragraph
 * so the inline rules can process each `$...$` individually), otherwise the
 * trailing inline content would be swallowed into a corrupted display math block.
 *
 * Note: any `$$` pair with trailing content (including malformed inputs with
 * multiple `$$` pairs) falls back to a paragraph, keeping the line literal.
 */
const hasDollarPairWithTrailingContent = (state: StateBlock, pos: number, end: number): boolean => {
  const isWhiteSpace = state.md.utils.isWhiteSpace;

  for (let i = pos; i < end - 1; i++) {
    if (state.src.charCodeAt(i) !== 36 /* $ */ || state.src.charCodeAt(i + 1) !== 36 /* $ */)
      continue;

    // Found a closing $$ pair, check whether non-whitespace content follows it
    for (let j = i + 2; j < end; j++) if (!isWhiteSpace(state.src.charCodeAt(j))) return true;

    // The pair sits at the end of the line, it's a normal single line expression
    break;
  }

  return false;
};

/*
 * Parse block math with dollar signs: $$...$$
 */
const dollarBlockTexRule: BlockRule = (state, startLine, endLine, silent) => {
  const { src } = state;
  const start = state.bMarks[startLine] + state.tShift[startLine];
  const end = state.eMarks[startLine];

  if (src.charCodeAt(start) !== 36 /* $ */ || src.charCodeAt(start + 1) !== 36 /* $ */)
    return false;

  // A single-line $$...$$ pair followed by non-whitespace content must not be
  // treated as a block: fall back to paragraph so the trailing inline math is
  // parsed by the inline rules instead of being swallowed into the block.
  if (hasDollarPairWithTrailingContent(state, start + 2, end)) return false;

  const contentEnd = skipWhitespaceBack(state, end, start);
  const pos = start + 2;

  // Single line expression
  const singleLine = endsWithMarker(src, pos, contentEnd, 36 /* $ */, 36 /* $ */);
  const closingLine = singleLine ? startLine : findBlockClose(state, startLine, endLine, 36, 36);

  if (closingLine === -1) return false;

  // In silent mode markdown-it only probes whether the line starts a block.
  // Report a match only when the closing `$$` is actually found, otherwise the
  // paragraph would be split and the rest of the document would be swallowed.
  if (silent) return true;

  const firstLine = src.slice(pos, singleLine ? contentEnd - 2 : end);
  let lastLine = "";

  if (!singleLine) {
    const lastStart = state.bMarks[closingLine] + state.tShift[closingLine];

    lastLine = src.slice(
      lastStart,
      skipWhitespaceBack(state, state.eMarks[closingLine], lastStart) - 2,
    );
  }

  state.line = closingLine + 1;

  const token = state.push("math_block", "math", 0);

  token.block = true;
  token.content =
    (firstLine ? `${firstLine}\n` : "") +
    state.getLines(startLine + 1, closingLine, state.sCount[startLine], true) +
    (lastLine ? `${lastLine}\n` : "");
  token.map = [startLine, state.line];
  token.markup = "$$";

  return true;
};

/*
 * Parse block math with bracket syntax: \[...\]
 */
const bracketBlockTexRule: BlockRule = (state, startLine, endLine, silent) => {
  const { src } = state;
  const start = state.bMarks[startLine] + state.tShift[startLine];
  const end = state.eMarks[startLine];

  if (src.charCodeAt(start) !== 92 /* \ */ || src.charCodeAt(start + 1) !== 91 /* [ */)
    return false;

  const contentEnd = skipWhitespaceBack(state, end, start);
  const pos = start + 2;

  // Single line expression
  const singleLine = endsWithMarker(src, pos, contentEnd, 92 /* \ */, 93 /* ] */);
  const closingLine = singleLine
    ? startLine
    : findBlockClose(state, startLine, endLine, 92 /* \ */, 93 /* ] */);

  if (closingLine === -1) return false;

  // In silent mode markdown-it only probes whether the line starts a block.
  // Report a match only when the closing `\]` is actually found, otherwise the
  // paragraph would be split even though the content is not a math block.
  if (silent) return true;

  const firstLine = src.slice(pos, singleLine ? contentEnd - 2 : end);
  let lastLine = "";

  if (!singleLine) {
    const lastStart = state.bMarks[closingLine] + state.tShift[closingLine];

    lastLine = src.slice(
      lastStart,
      skipWhitespaceBack(state, state.eMarks[closingLine], lastStart) - 2,
    );
  }

  state.line = closingLine + 1;

  const token = state.push("math_block", "math", 0);

  token.block = true;
  token.content =
    (firstLine ? `${firstLine}\n` : "") +
    state.getLines(startLine + 1, closingLine, state.sCount[startLine], true) +
    (lastLine ? `${lastLine}\n` : "");
  token.map = [startLine, state.line];
  token.markup = BLOCK_MARKER;

  return true;
};

const ruleOptions = {
  alt: ["paragraph", "reference", "blockquote", "list"],
};

export const tex: PluginWithOptions<MarkdownItTexOptions> = (md, options) => {
  if (typeof options?.render !== "function")
    throw new TypeError('[@mdit/plugin-tex]: "render" option should be a function');

  const {
    allowInlineWithSpace = false,
    mathFence = false,
    delimiters = "dollars",
    render,
  } = options;

  // Repeated installation is a full no-op: a second call must not stack the fence wrapper,
  // merge another delimiter's rules or replace the first installation's renderers.
  const installed =
    hasRule(md, "math_inline_dollar", "inline") ||
    hasRule(md, "math_block_dollar", "block") ||
    hasRule(md, "math_inline_bracket", "inline") ||
    hasRule(md, "math_block_bracket", "block");

  if (installed) return;

  // Handle ```math blocks
  if (mathFence) {
    const fence = md.renderer.rules.fence;

    md.renderer.rules.fence = (tokens, index, mdItOptions, env, self): string => {
      const token = tokens[index];

      if (token.info.trim() === "math")
        // oxlint-disable-next-line typescript/no-non-null-assertion
        return render(token.content, true, env!);

      return fence(tokens, index, mdItOptions, env, self);
    };
  }

  // Register inline and block rules based on delimiters option
  if (delimiters === "dollars" || delimiters === "all") {
    md.inline.ruler.after(
      "escape",
      "math_inline_dollar",
      createDollarInlineTexRule(allowInlineWithSpace),
    );
    md.block.ruler.after("blockquote", "math_block_dollar", dollarBlockTexRule, ruleOptions);
  }

  if (delimiters === "brackets" || delimiters === "all") {
    md.inline.ruler.before("escape", "math_inline_bracket", createBracketInlineTexRule());
    md.block.ruler.after("blockquote", "math_block_bracket", bracketBlockTexRule, ruleOptions);
  }

  md.renderer.rules.math_inline = (tokens, index, _options, env): string =>
    // oxlint-disable-next-line typescript/no-non-null-assertion
    render(tokens[index].content, false, env!);
  md.renderer.rules.math_block = (tokens, index, _options, env): string =>
    // oxlint-disable-next-line typescript/no-non-null-assertion
    render(tokens[index].content, true, env!);
};
